import functools

call_log = []

def log_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        call_log.append(func.__name__)
        return func(*args, **kwargs)
    return wrapper

visibleTests:
@log_calls
def double(x):
    return x * 2
assert double(5) == 10
assert double.__name__ == 'double'
assert call_log == ['double']

